-- SQLite schema is also initialized idempotently by api/index.php.
PRAGMA foreign_keys=ON;
CREATE TABLE IF NOT EXISTS users(id INTEGER PRIMARY KEY, name TEXT NOT NULL, email TEXT UNIQUE NOT NULL, password TEXT NOT NULL, created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS products(id INTEGER PRIMARY KEY, slug TEXT UNIQUE NOT NULL, title TEXT NOT NULL, category TEXT NOT NULL, genres TEXT NOT NULL DEFAULT '[]', platform TEXT NOT NULL, region TEXT NOT NULL, description TEXT NOT NULL, image TEXT NOT NULL, popularity INTEGER DEFAULT 0);
CREATE TABLE IF NOT EXISTS wishlist(user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE, product_id INTEGER NOT NULL REFERENCES products(id) ON DELETE CASCADE, created_at TEXT DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY(user_id,product_id));
CREATE TABLE IF NOT EXISTS offers(id INTEGER PRIMARY KEY, product_id INTEGER NOT NULL REFERENCES products(id), seller TEXT NOT NULL, price REAL NOT NULL, old_price REAL, stock INTEGER DEFAULT 20);
CREATE TABLE IF NOT EXISTS keys_inventory(id INTEGER PRIMARY KEY, offer_id INTEGER NOT NULL REFERENCES offers(id), license_key TEXT UNIQUE NOT NULL, sold INTEGER DEFAULT 0);
CREATE TABLE IF NOT EXISTS orders(id INTEGER PRIMARY KEY, user_id INTEGER NOT NULL REFERENCES users(id), total REAL NOT NULL, created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS order_items(id INTEGER PRIMARY KEY, order_id INTEGER NOT NULL REFERENCES orders(id), product_title TEXT NOT NULL, quantity INTEGER NOT NULL, price REAL NOT NULL, license_key TEXT NOT NULL);
